import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Handle, Position } from 'reactflow'; // Import Position from reactflow
import BaseNode from './BaseNode';

// Color mapping (reuse the same one from BaseNode.jsx for consistency)
const NODE_COLORS = {
  customInput: { header: '#0ea5e9', bg: '#f0f9ff' },
  llm: { header: '#8b5cf6', bg: '#f3e8ff' },
  customOutput: { header: '#ec4899', bg: '#fdf2f8' },
  text: { header: '#10b981', bg: '#f0fdf4' },
  math: { header: '#f59e0b', bg: '#fffbeb' },
  api: { header: '#3b82f6', bg: '#dbeafe' },
  condition: { header: '#ef4444', bg: '#fef2f2' },
  csv: { header: '#059669', bg: '#f0fdf4' },
  custom: { header: '#6b7280', bg: '#f3f4f6' },
};

export const TextNode = ({ data }) => {
  const [text, setText] = useState(data.text || '');
  const textareaRef = useRef(null);
  const colors = NODE_COLORS.text || NODE_COLORS.custom; // Get the specific color for text node

  // Auto-resize the textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.max(textareaRef.current.scrollHeight, 60) + 'px';
    }
  }, [text]);

  // Extract variables like {{input}}
  const variables = useMemo(() => {
    const matches = text.match(/{{\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*}}/g) || [];
    return [...new Set(matches.map(v => v.slice(2, -2).trim()))];
  }, [text]);

  // Calculate dynamic handle positions for variables
  const dynamicHandles = variables.map((variable, index) => {
    // Distribute handles vertically along the left edge
    const positionPercentage = ((index + 1) * 100) / (variables.length + 1);
    return {
      id: variable,
      type: 'target', // Input handle
      position: Position.Left, // Use Position enum
      style: {
        top: `${positionPercentage}%`,
        background: colors.header, // Use the node's header color
        border: '2px solid white',
      },
    };
  });

  // Combine dynamic handles with the fixed output handle
  const allHandles = [
    ...dynamicHandles,
    {
      id: 'output',
      type: 'source', // Output handle
      position: Position.Right, // Use Position enum
      style: {
        background: colors.header, // Use the node's header color
        border: '2px solid white',
      }
    }
  ];

  return (
    <div
      style={{
        width: '220px',
        borderRadius: '8px',
        border: `1px solid ${colors.header}`,
        backgroundColor: colors.bg,
        boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        fontFamily: "'Inter', sans-serif",
        position: 'relative', // Important for absolute positioned handles
      }}
    >
      <div
        style={{
          padding: '8px 12px',
          backgroundColor: colors.header,
          color: 'white',
          fontSize: '13px',
          fontWeight: 600,
          borderBottom: `1px solid ${colors.header}`,
        }}
      >
        TEXT
      </div>
      <div style={{ padding: '10px 12px', fontSize: '13px', color: '#374151' }}>
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          className="w-full p-1 text-xs border rounded focus:ring-1 focus:ring-blue-500 resize-none"
          placeholder="Enter text... Use {{variable}} for inputs"
          style={{
            minHeight: '60px',
            overflow: 'hidden',
            height: 'auto',
            width: '100%', // Ensure textarea fills container
          }}
        />
        {variables.length > 0 && (
          <div className="mt-2 text-xs text-gray-600">
            Variables: {variables.map(v => (
              <span
                key={v}
                className="inline-block px-1 py-0.5 mx-0.5 text-xs bg-blue-100 text-blue-800 rounded"
              >
                {v}
              </span>
            ))}
          </div>
        )}
      </div>
      {/* Render all handles */}
      {allHandles.map(handle => (
        <Handle
          key={handle.id}
          type={handle.type}
          position={handle.position}
          id={handle.id}
          style={handle.style}
        />
      ))}
      {/* Optional: Add variable labels next to handles */}
      {variables.map((variable, index) => {
        const positionPercentage = ((index + 1) * 100) / (variables.length + 1);
        return (
          <div
            key={`label-${variable}`}
            style={{
              position: 'absolute',
              left: '-60px', // Adjust as needed
              top: `calc(${positionPercentage}% - 10px)`, // Align label with handle
              fontSize: '10px',
              fontWeight: '500',
              color: colors.header, // Match the handle color
              background: 'white',
              padding: '2px 6px',
              borderRadius: '4px',
              border: `1px solid ${colors.header}`,
              whiteSpace: 'nowrap',
              pointerEvents: 'none', // Allow clicking through to the handle
            }}
          >
            {variable}
          </div>
        );
      })}
    </div>
  );
};
